const municipioId = $('Para cada município').item.json.id;
const response = $input.first().json;
const itens = response.items || [];
if (itens.length === 0) return [];
const v = itens[0];
if (!v?.id?.videoId) return [];
return [{
  json: {
    municipioId,
    videoId: v.id.videoId,
    videoTitle: v.snippet?.title || '',
    videoUrl: `https://www.youtube.com/watch?v=${v.id.videoId}`,
  }
}];

function normalizar(s) {
  return (s || "").toString().normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
}

const PALAVRAS_APOIO = ["otimo", "excelente", "parabens", "finalmente", "merecido", "sucesso", "gostei", "adorei", "orgulho", "apoio total", "show de bola"];
const PALAVRAS_CRITICA = ["vergonha", "ladrao", "roubo", "corrupcao", "mentira", "pessimo", "decepcao", "revoltante", "absurdo", "descaso", "cadeia"];
const PALAVRAS_ALERTA = ["cuidado", "desconfio", "so promessa", "so no papel", "acredito quando ver", "propaganda enganosa", "ja ouvi isso antes"];

function contemAlguma(texto, lista) {
  return lista.some(p => texto.includes(p));
}

function classificar(texto) {
  const t = normalizar(texto);
  if (contemAlguma(t, PALAVRAS_CRITICA)) return "critica";
  if (contemAlguma(t, PALAVRAS_ALERTA)) return "alerta";
  if (contemAlguma(t, PALAVRAS_APOIO)) return "apoio";
  if (t.includes("?")) return "duvida";
  return "duvida";
}

const contexto = $('Extrair vídeo em destaque').item.json;
const response = $input.first().json;
const comentarios = response.items || [];

const resultado = [];
for (const c of comentarios) {
  const top = c.snippet?.topLevelComment?.snippet;
  if (!top?.textDisplay) continue;
  resultado.push({
    json: {
      municipio_id: contexto.municipioId,
      source: "YouTube",
      author_name: top.authorDisplayName || "Anônimo",
      comment_text: top.textDisplay.slice(0, 800),
      sentiment: classificar(top.textDisplay),
      video_title: contexto.videoTitle,
      video_url: contexto.videoUrl,
      external_id: c.id,
      published_at: top.publishedAt || null,
    }
  });
}
return resultado;
